  "items": [
    {
      "original_text": "sprint-drift-check.sh follows relates_to links on the current epic: when a related epic transitioned to closed after the implementation plan was created, emit REPLAN_TRIGGER with the closed epic ID and a summary of what changed \u2014 using the same contract as git-history drift detection",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable behavioral capability of the script to detect and emit drift signals when related epics close, not a one-time task"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Drift detection is one-hop only: checks direct relates_to neighbors, not neighbors-of-neighbors",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable system behavior constraint that persists after implementation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "Brainstorm's Part C scan suggests relates_to links to open (not closed/archived) epics when cross-epic artifact overlap is discovered during gap analysis",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes an ongoing system behavior where the scan produces and suggests specific link types based on discovered conditions"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "The relates_to link suggestion is presented to the user for approval before creating the link",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes an ongoing system behavior where link suggestions require user approval before creation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "After deployment, if two epics are linked via relates_to and one closes, the next sprint drift check on the other epic's stories emits REPLAN_TRIGGER \u2014 verified by test scenario with two linked epics",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior (trigger emission upon specific conditions) that persists after deployment, phrased as ongoing functionality despite the test verification framing"
